package com.drogaria.backend.service;
import com.drogaria.backend.dto.SolicitacaoCadastroResponse; import com.drogaria.backend.entity.SolicitacaoCadastro; import com.drogaria.backend.exception.ApiException; import com.drogaria.backend.repository.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import java.time.LocalDate; import java.util.List;
@Service public class SolicitacaoCadastroService { private final SolicitacaoCadastroRepository r; private final ClienteRepository clientes; private final FuncionarioRepository funcionarios; public SolicitacaoCadastroService(SolicitacaoCadastroRepository r,ClienteRepository c,FuncionarioRepository f){this.r=r;clientes=c;funcionarios=f;} public List<SolicitacaoCadastroResponse> listar(){return r.findAll().stream().map(SolicitacaoCadastroResponse::new).toList();} public SolicitacaoCadastroResponse analisar(Integer id,String status,Integer idFuncionario){SolicitacaoCadastro s=r.findById(id).orElseThrow(()->new ApiException("Solicitacao nao encontrada",HttpStatus.NOT_FOUND));s.setStatus(status);s.setDataAnalise(LocalDate.now());if(idFuncionario!=null)s.setFuncionario(funcionarios.findById(idFuncionario).orElseThrow(()->new ApiException("Funcionario nao encontrado",HttpStatus.NOT_FOUND)));if("APROVADA".equalsIgnoreCase(status)){s.getCliente().setContaAprovada(true);clientes.save(s.getCliente());}return new SolicitacaoCadastroResponse(r.save(s));} }